import heapq
from collections import Counter, defaultdict

def count_neighbors(visited, grid, row, col):
    count = 0
    for i in [-1, 0, 1]:
        for j in [-1, 0, 1]:

            r, c = row + i, col + j

            if 0 <= r < len(grid) and 0 <= c < len(grid[0]) and not visited[r][c]:
                count += 1
    return count

def visibility_score(node, neighbors, nodes_idx, points):
    return (node[0] + node[1] + node[2],
            points - sum(x**2 for x in neighbors[node]))

